import sqlglot
from sqlglot import exp

MAX_ROWS = 10_000
WRITES = (exp.Insert, exp.Update, exp.Delete, exp.Merge, exp.Create, exp.Drop)

def validate(sql: str, allowed: set[str], dialect: str = "snowflake") -> str:
    stmts = sqlglot.parse(sql, read=dialect)          # raises on syntax errors
    if len(stmts) != 1:
        raise ValueError("exactly one statement")
    tree = stmts[0]
    if not isinstance(tree, (exp.Select, exp.Union)) or tree.find(*WRITES):
        raise ValueError("read-only SELECT only")      # the DB role is read-only too
    ctes = {c.alias_or_name.lower() for c in tree.find_all(exp.CTE)}
    for t in tree.find_all(exp.Table):
        name = f"{t.db}.{t.name}".lower()
        if t.name.lower() not in ctes and name not in allowed:
            raise ValueError(f"table not allowed for this user: {name}")
    if not tree.args.get("limit"):
        tree = tree.limit(MAX_ROWS)
    return tree.sql(dialect=dialect)

